// Writes dist/.htaccess: security headers, caching, clean 404, and noindex on previews.
import fs from 'node:fs';
const preview = process.env.PREVIEW === '1';
const lines = [
	'# Generated by scripts/postbuild.mjs',
	'Options -Indexes',
	'DirectoryIndex index.html',
	'ErrorDocument 404 /404.html',
	'',
	'RewriteEngine On',
	'RewriteCond %{HTTPS} !=on',
	'RewriteCond %{HTTP:X-Forwarded-Proto} !https',
	'RewriteRule ^ https://%{HTTP_HOST}%{REQUEST_URI} [L,R=301]',
	'',
	'<IfModule mod_headers.c>',
	`  Header always set Content-Security-Policy "default-src 'self'; img-src 'self' data:; style-src 'self'; font-src 'self'; script-src 'self'; connect-src 'self'; base-uri 'self'; form-action 'self' https://aossi.org; frame-ancestors 'none'; object-src 'none'; upgrade-insecure-requests"`,
	'  Header always set X-Content-Type-Options "nosniff"',
	'  Header always set Referrer-Policy "strict-origin-when-cross-origin"',
	'  Header always set Permissions-Policy "camera=(), microphone=(), geolocation=(), interest-cohort=()"',
	'  Header always set X-Frame-Options "DENY"',
	'  Header always set Cross-Origin-Opener-Policy "same-origin"',
	preview ? '  Header always set X-Robots-Tag "noindex, nofollow"' : null,
	'  <FilesMatch "\\.(html)$">',
	'    Header set Cache-Control "public, max-age=300, must-revalidate"',
	'  </FilesMatch>',
	'</IfModule>',
	'',
	'<IfModule mod_expires.c>',
	'  ExpiresActive On',
	'  ExpiresByType image/avif "access plus 1 year"',
	'  ExpiresByType image/webp "access plus 1 year"',
	'  ExpiresByType font/woff2 "access plus 1 year"',
	'</IfModule>',
	'<IfModule mod_headers.c>',
	'  <If "%{REQUEST_URI} =~ m#^/_astro/#">',
	'    Header set Cache-Control "public, max-age=31536000, immutable"',
	'  </If>',
	'</IfModule>',
	'',
	'AddType image/avif .avif',
	'AddType font/woff2 .woff2',
	'<IfModule mod_deflate.c>',
	'  AddOutputFilterByType DEFLATE text/html text/css text/plain application/javascript image/svg+xml application/xml application/json',
	'</IfModule>',
	'',
].filter((l) => l !== null);
fs.writeFileSync('dist/.htaccess', lines.join('\n'));
console.log(`.htaccess written (preview=${preview})`);
